package com.seasonaldining.recommendation.controller;
import com.seasonaldining.common.response.ApiResponse; import com.seasonaldining.common.security.CurrentUserProvider; import com.seasonaldining.recommendation.dto.request.*; import com.seasonaldining.recommendation.dto.response.*; import com.seasonaldining.recommendation.service.*; import com.seasonaldining.shopping.dto.response.ShoppingPlanResponse; import io.swagger.v3.oas.annotations.Operation; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/recommendations/plans") @Tag(name="12. AI Recommendations",description="추천 API") public class RecommendationController{private final RecommendationPlanService service;private final RecommendationMessageService messages;private final CurrentUserProvider current;public RecommendationController(RecommendationPlanService s,RecommendationMessageService m,CurrentUserProvider c){service=s;messages=m;current=c;}@PostMapping @Operation(summary="장보기 계획 생성") public ApiResponse<ShoppingPlanResponse> create(@Valid @RequestBody CreateShoppingPlanRequest r){return ApiResponse.success(service.create(current.getCurrentUserId(),r),null);}@GetMapping("/{planId}") @Operation(summary="추천 계획 조회") public ApiResponse<ShoppingPlanResponse> get(@PathVariable Long planId){return ApiResponse.success(service.get(current.getCurrentUserId(),planId),null);}@PostMapping("/{planId}/messages") @Operation(summary="추천 수정 메시지 등록") public ApiResponse<RecommendationMessageResponse> message(@PathVariable Long planId,@Valid @RequestBody CreateRecommendationMessageRequest r){return ApiResponse.success(messages.add(current.getCurrentUserId(),planId,r.content()),null);}}
